def resolve_temporal_relation(direct_value, relation, query_year, event_date, activity_start, activity_end, status_start, status_end):
    if isinstance(direct_value, bool):
        return {'value': direct_value, 'open_dependencies': []}
    if relation == 'more_than_half_calendar_year':
        if not isinstance(query_year, int) or isinstance(query_year, bool):
            return {'value': None, 'open_dependencies': ['query_year is required for the calendar-year residence comparison']}
        if not isinstance(activity_start, str) or not isinstance(activity_end, str):
            return {'value': None, 'open_dependencies': ['the explicit start and end dates of the shared-principal-abode interval are required']}
        overlap = inclusive_year_overlap_days(activity_start, activity_end, query_year)
        return {'value': overlap * 2 > year_days(query_year), 'open_dependencies': []}
    if relation == 'event_in_either_two_preceding_calendar_years':
        if not isinstance(query_year, int) or isinstance(query_year, bool):
            return {'value': None, 'open_dependencies': ['query_year is required for the preceding-calendar-year comparison']}
        if not isinstance(event_date, str):
            return {'value': None, 'open_dependencies': ['the explicit event date is required']}
        event_year = calendar_year(event_date)
        return {'value': event_year == query_year - 1 or event_year == query_year - 2, 'open_dependencies': []}
    if relation == 'activity_entirely_during_status':
        values = (activity_start, activity_end, status_start, status_end)
        if not all(isinstance(value, str) for value in values):
            return {'value': None, 'open_dependencies': ['explicit activity and status start and end dates are required']}
        calendar_year(activity_start)
        calendar_year(activity_end)
        calendar_year(status_start)
        calendar_year(status_end)
        if activity_end < activity_start:
            raise ValueError('The observed activity interval ends before it begins')
        if status_end < status_start:
            raise ValueError('The observed status interval ends before it begins')
        return {'value': status_start <= activity_start and activity_end <= status_end, 'open_dependencies': []}
    raise ValueError('Unknown source-selected temporal relation')

def qualifying_child(facts):
    stated = facts.get('individual_is_qualifying_child_of_this_taxpayer')
    if isinstance(stated, bool):
        return {'value': stated, 'used_units': ['u152_c1_pred'], 'open_dependencies': []}

    relationship_ok = facts.get('relationship_described_in_section152_c2')
    relationship_open = []
    if not isinstance(relationship_ok, bool):
        relationship_ok = None
        relationship = facts.get('relationship_to_taxpayer')
        if isinstance(relationship, str):
            normalized = relationship.strip().lower().replace('-', '_').replace(' ', '_')
            allowed = ('child', 'descendant_of_child', 'grandchild', 'brother', 'sister', 'stepbrother', 'stepsister', 'descendant_of_brother', 'descendant_of_sister', 'niece', 'nephew')
            if normalized in allowed:
                relationship_ok = True
            else:
                relationship_open.append('relationship_to_taxpayer does not identify a relationship supplied by section 152(c)(2)')
        else:
            relationship_open.append('a GIVEN section 152(c)(2) relationship or the underlying relationship is required')

    abode = resolve_temporal_relation(
        facts.get('given_same_principal_abode_more_than_half_taxable_year'),
        'more_than_half_calendar_year',
        facts.get('query_year'),
        None,
        facts.get('principal_abode_co_residence_start_date'),
        facts.get('principal_abode_co_residence_end_date'),
        None,
        None)

    age_ok = facts.get('given_section152_c3_age_requirements_met')
    age_open = []
    if not isinstance(age_ok, bool):
        child_age = facts.get('individual_age_at_end_of_taxable_year')
        taxpayer_age = facts.get('taxpayer_age_at_end_of_taxable_year')
        if (isinstance(child_age, int) and not isinstance(child_age, bool) and
                isinstance(taxpayer_age, int) and not isinstance(taxpayer_age, bool)):
            age_ok = child_age < taxpayer_age and child_age < 25
        else:
            age_ok = None
            age_open.append('a GIVEN section 152(c)(3) age conclusion or both end-of-year ages is required')

    filed_joint = facts.get('individual_filed_joint_return_with_spouse')
    refund_only = facts.get('joint_return_filed_only_for_refund')
    joint_ok = None
    joint_open = []
    if isinstance(filed_joint, bool):
        if not filed_joint:
            joint_ok = True
        elif isinstance(refund_only, bool):
            joint_ok = refund_only
        else:
            joint_open.append('joint_return_filed_only_for_refund is required when a joint return was filed')
    else:
        joint_open.append('individual_filed_joint_return_with_spouse is required')

    conditions = (relationship_ok, abode.get('value'), age_ok, joint_ok)
    if False in conditions:
        return {'value': False, 'used_units': ['u152_c1_pred'], 'open_dependencies': []}
    if None not in conditions:
        return {'value': True, 'used_units': ['u152_c1_pred'], 'open_dependencies': []}
    open_dependencies = []
    for item in relationship_open + abode.get('open_dependencies', []) + age_open + joint_open:
        if item not in open_dependencies:
            open_dependencies.append(item)
    return {'value': None, 'used_units': ['u152_c1_pred'], 'open_dependencies': open_dependencies}

def penal_institution_service_exclusion_applies(facts):
    stated = facts.get('service_performed_by_person_committed_to_penal_institution')
    if isinstance(stated, bool):
        return {'value': stated, 'used_units': ['u3306_c21_pred'], 'open_dependencies': []}
    penal = facts.get('institution_is_penal_institution')
    if penal is False:
        return {'value': False, 'used_units': ['u3306_c21_pred'], 'open_dependencies': []}
    resolved = resolve_temporal_relation(
        facts.get('given_person_committed_to_penal_institution_during_service'),
        'activity_entirely_during_status',
        None,
        None,
        facts.get('service_start_date'),
        facts.get('service_end_date'),
        facts.get('penal_commitment_start_date'),
        facts.get('penal_commitment_end_date'))
    if resolved.get('value') is False:
        return {'value': False, 'used_units': ['u3306_c21_pred'], 'open_dependencies': []}
    if penal is True and resolved.get('value') is True:
        return {'value': True, 'used_units': ['u3306_c21_pred'], 'open_dependencies': []}
    open_dependencies = list(resolved.get('open_dependencies', []))
    if not isinstance(penal, bool):
        open_dependencies.append('institution_is_penal_institution is required')
    return {'value': None, 'used_units': ['u3306_c21_pred'], 'open_dependencies': open_dependencies}

